    let content: Content

    public init(_ title: String, @ViewBuilder content: () -> Content) {
        self.title = title
        self.content = content()
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title.uppercased())
                .font(.system(size: 10, weight: .bold))
                .foregroundColor(CaptureOneTheme.Colors.textSecondary)
                .padding(.bottom, 2)

            content
        }
        .padding(10)
        .background(CaptureOneTheme.Colors.toolBackground)
        .cornerRadius(4)
    }
}

/// Simplified POCheckboxStyle for internal UI verification.
public struct POCheckboxStyle: ToggleStyle {
    public func makeBody(configuration: Configuration) -> some View {
        HStack {
            Image(systemName: configuration.isOn ? "checkmark.square.fill" : "square")
                .font(.system(size: 11))
                .foregroundColor(configuration.isOn ? CaptureOneTheme.Colors.activeHighlight : .gray)
                .onTapGesture {
                    configuration.isOn.toggle()
                }
            configuration.label
        }
    }
}

