+                    .padding(4)
+                    .onTapGesture {
+                        pickedState.togglePicked(for: url)
+                    }
+            }
+            
+            Text(url.lastPathComponent)
+                .font(.system(size: 9))
+                .lineLimit(1)
+                .padding(.top, 2)
+        }
+        .frame(width: 120)
+    }
+}
